@Service
public class DataProcessor {
    @Async
    private void processInternal() { }   // private — silent no-op

    @Async
    public final void processFinal() { }  // final — CGLIB не переопределит

    @Async
    public static void processStatic() { } // static — AOP игнорирует

    @Async
    public void processCorrectly() { }     // public/non-final/instance — ок

    public void caller() {
        processInternal();              // синхронно (private)
        processFinal();                 // синхронно (final)
        DataProcessor.processStatic();  // синхронно (static)
        processCorrectly();             // тоже синхронно — self-invocation!
    }
}
